bounded_host_request.command:
set -eu
cid=gace-createvdobot-videobot-poll-1
new=create-videobot:reissue-invoice-fd5f32aa47e3c8559fe252244919bd736a267119
test "$(docker inspect "$cid" --format '{{.State.Running}}')" = true || exit 41
test "$(docker inspect "$cid" --format '{{.Image}}')" = "$(docker image inspect "$new" --format '{{.Id}}')" || exit 42
test "$(docker ps --filter label=com.docker.compose.project=gace-createvdobot --filter label=com.docker.compose.service=videobot-poll -q | wc -l)" -eq 1 || exit 43
docker exec -w /opt/videobot "$cid" node /opt/videobot/src/operations/runReissuedVideoInvoice.mjs || exit 44
docker exec -i "$cid" node --input-type=module <<'NODE'
import fs from 'node:fs';import pg from 'pg';
const pool=new pg.Pool({host:process.env.VIDEOBOT_DB_HOST,user:process.env.VIDEOBOT_DB_USER,database:process.env.VIDEOBOT_DB_NAME,password:fs.readFileSync('/run/secrets/videobot_db_password','utf8').trim(),max:1});
try{
 const offer=(await pool.query(`SELECT r.delivery_key,r.status,r.sale_mode,r.free_message_ids,r.paid_message_id,l.status listing_status
 FROM videobot_post_receipts r JOIN videobot_listings l USING(listing_id)
 WHERE r.delivery_key='v26nov24invoice:1'`)).rows;
 if(offer.length!==1||offer[0].status!=='sent'||offer[0].sale_mode!=='invoice'||
    offer[0].listing_status!=='published'||
    offer[0].free_message_ids?.length!==2||
    Number(offer[0].paid_message_id)!==Number(offer[0].free_message_ids[1]))
   process.exitCode=1;
 const old=(await pool.query("SELECT COUNT(DISTINCT delivery_key)::int AS n FROM videobot_stars_ledger WHERE kind='paid'")).rows[0];
 if(old.n!==1)process.exitCode=2;
}finally{await pool.end()}
NODE
test "$?" -eq 0 || exit 45
echo VIDEO_ONE_NEW_INVOICE_SALE_POST_AND_ORIGINAL_BUYER_LEDGER_PASS
